import { Ionicons } from "@expo/vector-icons";
import AsyncStorage from "@react-native-async-storage/async-storage";
import * as ImagePicker from "expo-image-picker";
import { getOfferBadge, rankOffers, type NormalizedOffer, type ProductIdentification } from "@pricelens/shared";
import { useEffect, useMemo, useRef, useState } from "react";
import { ActivityIndicator, Alert, Image, KeyboardAvoidingView, Linking, Modal, Platform, Pressable, ScrollView, StyleSheet, Switch, Text, TextInput, useColorScheme, useWindowDimensions, View } from "react-native";
import { SafeAreaView, useSafeAreaInsets } from "react-native-safe-area-context";
import { currentIdToken, useAuth } from "../src/auth";
import { useSubscriptions } from "../src/subscriptions";
import { disablePushNotifications, enablePushNotifications } from "../src/notifications";
import { detectLanguage, languages, translator, type Language } from "../src/i18n";
import { filterOffers } from "../src/offer-filters";
import { ApiError, classifyApiFailure } from "../src/api-errors";
import { analysePurchase } from "../src/purchase-analysis";

type Screen = "home" | "results" | "saved" | "plans" | "profile";
type Appearance = "light" | "dark" | "system";
type Market = "PT" | "US" | "GB" | "FR" | "DE" | "ES" | "IT" | "NL" | "BE" | "IE" | "AT" | "CH" | "CA" | "AU" | "BR" | "AE" | "CN";
type SavedKind = "favorite" | "alert" | "history";
type SavedItem = { id:string; kind:SavedKind; title:string; subtitle:string; offer?:NormalizedOffer; imageUri?:string; alertPrice?:number; remoteId?:string; offerId?:string };
type RemotePriceAlert = { id:string; title:string; targetPrice:number; enabled:boolean; lastBestOffer?:NormalizedOffer };
type PriceObservation = { id:string; price:number; currency:string; storeName:string; observedAt:string };
type Notice = { title:string; message:string; tone:"success"|"warning"|"error" };
type T = ReturnType<typeof translator>;

const API = (process.env.EXPO_PUBLIC_API_BASE_URL ?? "https://pricelens-api-44ftuum65a-ew.a.run.app").replace(/\/$/, "");
const markets: Record<Market,{label:string;currency:string}> = {
  PT:{label:"Portugal",currency:"EUR"},
  ES:{label:"España",currency:"EUR"},
  FR:{label:"France",currency:"EUR"},
  DE:{label:"Deutschland",currency:"EUR"},
  IT:{label:"Italia",currency:"EUR"},
  NL:{label:"Nederland",currency:"EUR"},
  BE:{label:"Belgique",currency:"EUR"},
  IE:{label:"Ireland",currency:"EUR"},
  AT:{label:"Österreich",currency:"EUR"},
  CH:{label:"Schweiz",currency:"CHF"},
  GB:{label:"United Kingdom",currency:"GBP"},
  US:{label:"United States",currency:"USD"},
  CA:{label:"Canada",currency:"CAD"},
  AU:{label:"Australia",currency:"AUD"},
  BR:{label:"Brasil",currency:"BRL"},
  AE:{label:"Dubai · UAE",currency:"AED"},
  CN:{label:"中国 · China",currency:"CNY"}
};
const emptyId: ProductIdentification = { id:"pending", sourceType:"text", name:"", visibleFeatures:[], confidence:0, createdAt:new Date(0).toISOString() };
const light = { bg:"#F7F8FA", surface:"#FFFFFF", elevated:"#F1F4F8", ink:"#172033", muted:"#647084", subtle:"#929BAB", line:"#DDE2EA", primary:"#5278E8", primaryStrong:"#3158C8", primarySoft:"#EDF2FF", success:"#087F5B", successSoft:"#E9F8F1", warning:"#99620A", warningSoft:"#FFF6DA", danger:"#C24132", dangerSoft:"#FFF0EC" };
const dark: typeof light = { bg:"#101827", surface:"#1C2940", elevated:"#24334D", ink:"#F7F9FC", muted:"#B7C1D1", subtle:"#8C9AB0", line:"#34445E", primary:"#83A3FF", primaryStrong:"#A8BEFF", primarySoft:"#263B6A", success:"#66D6AE", successSoft:"#183A30", warning:"#F0C15B", warningSoft:"#3A3018", danger:"#FF9B8D", dangerSoft:"#451E1B" };
type Theme = typeof light;

export default function PriceLens() {
  const auth=useAuth();
  const subscriptions=useSubscriptions();
  const page=useRef<ScrollView>(null);
  const system = useColorScheme(); const insets = useSafeAreaInsets();
  const [language,setLanguageRaw]=useState<Language>(detectLanguage()); const [appearance,setAppearanceRaw]=useState<Appearance>("light");
  const [market,setMarketRaw]=useState<Market>("PT");
  const [screen,setScreen]=useState<Screen>("home"); const [id,setId]=useState<ProductIdentification>(emptyId);
  const [name,setName]=useState(""); const [brand,setBrand]=useState(""); const [model,setModel]=useState(""); const [category,setCategory]=useState(""); const [image,setImage]=useState("");
  const [offers,setOffers]=useState<NormalizedOffer[]>([]); const [saved,setSaved]=useState<SavedItem[]>([]); const [loading,setLoading]=useState(false); const [confirm,setConfirm]=useState(false); const [detail,setDetail]=useState<SavedItem|null>(null); const [notifications,setNotifications]=useState(false); const [savedReady,setSavedReady]=useState(false);
  const t=useMemo(()=>translator(language),[language]); const theme=appearance==="dark"||(appearance==="system"&&system==="dark")?dark:light; const s=useMemo(()=>styles(theme),[theme]);
  const favoriteOfferIds=useMemo(()=>new Set(saved.filter(x=>x.kind==="favorite").map(x=>x.offerId??x.offer?.id).filter(Boolean)),[saved]);
  const alertOfferIds=useMemo(()=>new Set(saved.filter(x=>x.kind==="alert").map(x=>x.offerId??x.offer?.id).filter(Boolean)),[saved]);
  const [notice,setNotice]=useState<Notice>({title:t("ready"),message:t("readyText"),tone:"success"}); const ranked=useMemo(()=>rankOffers(offers),[offers]);
  useEffect(()=>{setNotice({title:t("ready"),message:t("readyText"),tone:"success"})},[language]);
  useEffect(()=>{void(async()=>{const [l,a,m,stored,push]=await Promise.all([AsyncStorage.getItem("pricelens.language"),AsyncStorage.getItem("pricelens.appearance"),AsyncStorage.getItem("pricelens.market"),AsyncStorage.getItem("pricelens.saved"),AsyncStorage.getItem("pricelens.notifications")]);if(languages.some(x=>x.code===l))setLanguageRaw(l as Language);if(["light","dark","system"].includes(a??""))setAppearanceRaw(a as Appearance);if(m&&m in markets)setMarketRaw(m as Market);if(stored){try{setSaved(JSON.parse(stored) as SavedItem[])}catch{setSaved([])}}setNotifications(push==="true");setSavedReady(true)})()},[]);
  useEffect(()=>{if(savedReady)void AsyncStorage.setItem("pricelens.saved",JSON.stringify(saved))},[saved,savedReady]);
  useEffect(()=>{if(!auth.user||!savedReady)return;void apiRequest<{items:RemotePriceAlert[]}>("/price-alerts","GET").then(({items})=>setSaved(current=>{const other=current.filter(item=>item.kind!=="alert");const alerts=items.filter(item=>item.enabled).map(item=>({id:`alert_${item.id}`,kind:"alert" as const,title:item.title,subtitle:`${t("targetPrice")}: ${money(item.targetPrice,item.lastBestOffer?.currency)}`,offer:item.lastBestOffer,imageUri:item.lastBestOffer?.imageUrl,alertPrice:item.targetPrice,remoteId:item.id,offerId:item.lastBestOffer?.id}));return[...alerts,...other]})).catch(()=>undefined)},[auth.user?.uid,savedReady,language]);
  useEffect(()=>{if(!subscriptions.isPremium&&market!=="PT")setMarket("PT")},[subscriptions.isPremium,market]);
  const setLanguage=(v:Language)=>{setLanguageRaw(v);void AsyncStorage.setItem("pricelens.language",v)}; const setAppearance=(v:Appearance)=>{setAppearanceRaw(v);void AsyncStorage.setItem("pricelens.appearance",v)};
  const setMarket=(v:Market)=>{setMarketRaw(v);void AsyncStorage.setItem("pricelens.market",v)};
  const updateNotifications=async(v:boolean)=>{if(!auth.user){setScreen("profile");setNotice({title:t("signIn"),message:t("accountSync"),tone:"warning"});return}setNotifications(v);try{const enabled=v?await enablePushNotifications(language):(await disablePushNotifications(),false);setNotifications(enabled);await AsyncStorage.setItem("pricelens.notifications",String(enabled))}catch{setNotifications(!v);await AsyncStorage.setItem("pricelens.notifications",String(!v));setNotice({title:t("apiUnavailable"),message:t("notificationText"),tone:"error"})}};
  useEffect(()=>{if(auth.user&&notifications)void enablePushNotifications(language).catch(async()=>{setNotifications(false);await AsyncStorage.setItem("pricelens.notifications","false")})},[auth.user?.uid,language]);
  const money=(n:number,c="EUR")=>new Intl.NumberFormat(language==="pt"?"pt-PT":language,{style:"currency",currency:c}).format(n);
  const remember=(kind:SavedKind,title:string,subtitle:string,offer?:NormalizedOffer,alertPrice?:number,remoteId?:string)=>setSaved(items=>{const itemId=`${kind}_${offer?.id??Date.now()}`;const next=[{id:itemId,kind,title,subtitle,offer,imageUri:offer?.imageUrl??image,alertPrice,remoteId,offerId:offer?.id},...items.filter(x=>x.id!==itemId)];if(kind!=="history"||subscriptions.isPremium)return next;let count=0;return next.filter(item=>item.kind!=="history"||++count<=10)});
  const apply=(x:ProductIdentification)=>{setId(x);setName(x.name);setBrand(x.brand??"");setModel(x.model??"");setCategory(x.category??"")};
  async function choose(source:"camera"|"gallery") {
    if(loading)return;
    const permission=source==="camera"?await ImagePicker.requestCameraPermissionsAsync():await ImagePicker.requestMediaLibraryPermissionsAsync();
    if(!permission.granted){setNotice({title:t("permission"),message:t(source==="camera"?"cameraPermission":"photoPermission"),tone:"warning"});return}
    const result=source==="camera"?await ImagePicker.launchCameraAsync({base64:true,quality:.82}):await ImagePicker.launchImageLibraryAsync({base64:true,quality:.82,mediaTypes:ImagePicker.MediaTypeOptions.Images});
    if(result.canceled||!result.assets[0])return;
    const asset=result.assets[0];setImage(asset.uri);setLoading(true);
    try{if(!asset.base64)throw new Error("Image data unavailable");const x=await request<ProductIdentification>("/product-identifications/image",{imageBase64:asset.base64,mimeType:asset.mimeType??"image/jpeg",country:market,currency:markets[market].currency});if(!identified(x)){setId({...emptyId,sourceType:"image"});setOffers([]);setNotice({title:t("notIdentified"),message:t("noOffersHelp"),tone:"warning"});setScreen("results");return}apply(x);remember("history",x.name,t("imageAnalysis"));setConfirm(true)}catch(cause){setNotice(failureNotice(cause,t))}finally{setLoading(false)}
  }
  async function textSearch(){
    if(loading)return;
    const q=name.trim();if(!q){setNotice({title:t("searchByName"),message:t("emptySearch"),tone:"warning"});return}
    setLoading(true);
    try{const x=await request<ProductIdentification>("/product-identifications/text",{query:q,country:market,currency:markets[market].currency});apply(x);remember("history",x.name||q,t("textCompare"));setConfirm(true)}catch(cause){setNotice(failureNotice(cause,t))}finally{setLoading(false)}
  }
  async function compare(){
    if(loading)return;
    setConfirm(false);setScreen("results");setLoading(true);
    try{const r=await request<{results:NormalizedOffer[]}>("/searches/offers",{query:name,brand,model,category,country:market,currency:markets[market].currency,condition:"any",maxPrice:1500,freeShippingOnly:false});setOffers(r.results);setNotice({title:r.results.length?`${r.results.length} ${t("offersFound")}`:t("noOffers"),message:r.results.length?t("bestPrice"):t("noOffersHelp"),tone:r.results.length?"success":"warning"})}catch(cause){setOffers([]);setNotice(failureNotice(cause,t))}finally{setLoading(false)}
  }
  const favorite=(o:NormalizedOffer)=>{if(favoriteOfferIds.has(o.id)){setSaved(items=>items.filter(item=>item.kind!=="favorite"||(item.offerId??item.offer?.id)!==o.id));const result={title:t("save"),message:t("favoriteRemoved"),tone:"success" as const};setNotice(result);return}remember("favorite",o.title,`${o.storeName} · ${money(o.totalPrice,o.currency)}`,o);setNotice({title:t("save"),message:t("savedNotice"),tone:"success"})};
  const alert=async(o:NormalizedOffer):Promise<Notice>=>{const existing=saved.find(item=>item.kind==="alert"&&(item.offerId??item.offer?.id)===o.id);if(existing){try{await removeAlert(existing);const result={title:t("alerts"),message:t("alertRemoved"),tone:"success" as const};setNotice(result);return result}catch{const result={title:t("apiUnavailable"),message:t("searchFailed"),tone:"error" as const};setNotice(result);return result}}if(!subscriptions.isPremium){const result={title:t("premiumRequired"),message:t("premiumRequiredText"),tone:"warning" as const};setScreen("plans");setNotice(result);return result}if(!auth.user){const result={title:t("signIn"),message:t("accountSync"),tone:"warning" as const};setScreen("profile");setNotice(result);return result}const target=Math.max(.01,o.totalPrice*.9);try{const created=await request<{id:string}>("/price-alerts",{query:o.title,title:o.title,brand:o.brand,model:o.model,country:market,currency:o.currency,targetPrice:target,enabled:true,initialPrice:o.totalPrice,initialStoreName:o.storeName,initialOfferId:o.id,initialProductUrl:o.affiliateUrl??o.productUrl});remember("alert",o.title,`${t("targetPrice")}: ${money(target,o.currency)}`,o,target,created.id);const result={title:t("createAlert"),message:t("alertNotice"),tone:"success" as const};setNotice(result);return result}catch(cause){const capped=cause instanceof ApiError&&cause.code==="PRICE_ALERT_LIMIT_REACHED";const result={title:capped?t("alertLimitTitle"):t("apiUnavailable"),message:capped?t("alertLimit"):cause instanceof ApiError&&cause.message?cause.message:t("searchFailed"),tone:(capped?"warning":"error") as Notice["tone"]};setNotice(result);return result}};
  const editAlert=async(item:SavedItem,targetPrice:number)=>{let remoteId=item.remoteId;if(!remoteId){const response=await apiRequest<{items:Array<{id:string;title:string;targetPrice:number}>}>("/price-alerts","GET");remoteId=response.items.find(x=>x.title===item.title&&Math.abs(x.targetPrice-(item.alertPrice??targetPrice))<.01)?.id??response.items.find(x=>x.title===item.title)?.id}if(!remoteId)throw new Error("Price alert not found");await apiRequest(`/price-alerts/${remoteId}`,"PATCH",{targetPrice});const currency=item.offer?.currency;const updated={...item,remoteId,alertPrice:targetPrice,subtitle:`${t("targetPrice")}: ${money(targetPrice,currency)}`};setSaved(items=>items.map(x=>x.id===item.id?updated:x));setDetail(updated);setNotice({title:t("editAlert"),message:t("alertSaved"),tone:"success"})};
  const removeAlert=async(item:SavedItem)=>{let remoteId=item.remoteId;if(!remoteId){const response=await apiRequest<{items:Array<{id:string;title:string;enabled:boolean}>}>("/price-alerts","GET");remoteId=response.items.find(x=>x.enabled&&x.title===item.title)?.id}if(!remoteId)throw new Error("Price alert not found");await deleteApiRequest(`/price-alerts/${remoteId}`);setSaved(items=>items.filter(x=>x.id!==item.id&&x.remoteId!==remoteId));setDetail(current=>current?.id===item.id?null:current);setNotice({title:t("alerts"),message:t("alertRemoved"),tone:"success"})};
  return <SafeAreaView style={s.safe} edges={["top","left","right"]}><KeyboardAvoidingView style={s.fill} behavior={Platform.OS==="ios"?"padding":"height"}><Header s={s} theme={theme} t={t}/><ScrollView ref={page} style={s.fill} contentContainerStyle={s.content} keyboardShouldPersistTaps="handled" keyboardDismissMode="on-drag">
    {screen==="home"&&<Home s={s} theme={theme} t={t} name={name} setName={setName} image={image} loading={loading} notice={notice} camera={()=>void choose("camera")} gallery={()=>void choose("gallery")} search={()=>void textSearch()} focusSearch={()=>setTimeout(()=>page.current?.scrollToEnd({animated:true}),250)}/>}
    {screen==="results"&&<Results
      s={s} theme={theme} t={t} name={name} model={model} category={category} image={image}
      market={markets[market]} identified={identified(id)} offers={ranked} loading={loading}
      notice={notice} money={money} favorite={favorite} alert={alert} favoriteOfferIds={favoriteOfferIds} alertOfferIds={alertOfferIds} home={()=>setScreen("home")}
      photo={()=>void choose("camera")} open={o=>setDetail({id:`r_${o.id}`,kind:"history",title:o.title,subtitle:o.storeName,offer:o,imageUri:o.imageUrl})}
    />}
    {screen==="saved"&&<Saved s={s} theme={theme} t={t} items={saved} open={setDetail}/>} {screen==="plans"&&<Plans s={s} theme={theme} t={t}/>} {screen==="profile"&&<Profile s={s} theme={theme} t={t} language={language} setLanguage={setLanguage} appearance={appearance} setAppearance={setAppearance} notifications={notifications} setNotifications={v=>void updateNotifications(v)} market={market} setMarket={setMarket} premium={subscriptions.isPremium}/>}</ScrollView>
    <Tabs s={s} theme={theme} t={t} active={screen} change={setScreen} bottom={Math.max(insets.bottom,10)}/>
    <Confirm s={s} theme={theme} t={t} visible={confirm} bottom={Math.max(insets.bottom,16)} name={name} setName={setName} brand={brand} setBrand={setBrand} model={model} setModel={setModel} category={category} setCategory={setCategory} image={image} close={()=>setConfirm(false)} compare={()=>void compare()}/>
    <Product s={s} theme={theme} t={t} item={detail} offers={ranked} money={money} bottom={Math.max(insets.bottom,16)} close={()=>setDetail(null)} favorite={favorite} alert={alert} editAlert={editAlert} removeAlert={removeAlert} favoriteOfferIds={favoriteOfferIds} alertOfferIds={alertOfferIds}/>
  </KeyboardAvoidingView></SafeAreaView>
}

async function request<T>(path:string,body:unknown){return apiRequest<T>(path,"POST",body)}
async function deleteApiRequest(path:string){const [token,deviceId]=await Promise.all([currentIdToken(),anonymousDeviceId()]);const r=await fetch(`${API}${path}`,{method:"DELETE",headers:{"Content-Type":"application/json","X-Device-Id":deviceId,...(token?{Authorization:`Bearer ${token}`}:{})}});const payload=await r.json().catch(()=>({})) as Record<string,unknown>&{code?:string;message?:string};if(!r.ok)throw new ApiError(r.status,payload.code,payload.message,payload);return payload}
async function apiRequest<T>(path:string,method:"GET"|"POST"|"PATCH",body?:unknown){const [token,deviceId]=await Promise.all([currentIdToken(),anonymousDeviceId()]);const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),20000);const separator=path.includes("?")?"&":"?";const url=method==="GET"?`${API}${path}${separator}_=${Date.now()}`:`${API}${path}`;try{const r=await fetch(url,{method,signal:controller.signal,headers:{"Content-Type":"application/json","Cache-Control":"no-cache","X-Device-Id":deviceId,...(token?{Authorization:`Bearer ${token}`}:{})},...(body===undefined?{}:{body:JSON.stringify(body)})});const payload=await r.json().catch(()=>({})) as Record<string,unknown>&{code?:string;message?:string|string[]};const message=Array.isArray(payload.message)?payload.message.join(" "):payload.message;if(!r.ok)throw new ApiError(r.status,payload.code,message,payload);return payload as T}finally{clearTimeout(timeout)}}
async function anonymousDeviceId(){const key="pricelens.device-id";const stored=await AsyncStorage.getItem(key);if(stored)return stored;const created=`device_${Date.now()}_${Math.random().toString(36).slice(2,12)}`;await AsyncStorage.setItem(key,created);return created}
function failureNotice(cause:unknown,t:T):Notice{const kind=classifyApiFailure(cause);if(kind==="usage_guest")return{title:t("usageLimit"),message:t("guestLimit"),tone:"warning"};if(kind==="usage_starter")return{title:t("usageLimit"),message:t("starterLimit"),tone:"warning"};if(kind==="usage_premium")return{title:t("usageLimit"),message:t("premiumLimit"),tone:"warning"};if(kind==="authentication")return{title:t("signIn"),message:t("authenticationRequired"),tone:"warning"};if(kind==="rate_limit")return{title:t("searchFailed"),message:t("rateLimited"),tone:"warning"};if(kind==="network")return{title:t("apiUnavailable"),message:t("networkError"),tone:"error"};return{title:t("apiUnavailable"),message:t("searchFailed"),tone:"error"}}
const identified=(x:ProductIdentification)=>Boolean(x.name?.trim()||x.brand?.trim()||x.model?.trim());
type C={s:ReturnType<typeof styles>;theme:Theme;t:T};
function Header({s,theme,t}:C){return <View style={s.header}><View style={s.brandWrap}><View style={s.logo}><Ionicons name="search" size={19} color="#fff"/></View><View><Text style={s.brand}>PriceLens</Text><Text style={s.brandSub}>{t("tagline")}</Text></View></View><View style={s.trust}><Ionicons name="shield-checkmark-outline" size={21} color={theme.primaryStrong}/></View></View>}
function Home(p:C&{name:string;setName:(v:string)=>void;image:string;loading:boolean;notice:Notice;camera:()=>void;gallery:()=>void;search:()=>void;focusSearch:()=>void}){return <View style={p.s.stack}><View><Text style={p.s.hero}>{p.t("hero")}</Text><Text style={p.s.heroText}>{p.t("heroText")}</Text></View>{p.notice.tone!=="success"&&<NoticeBox {...p} notice={p.notice}/>}<View style={p.s.row}><Button {...p} label={p.loading?p.t("analysing"):p.t("takePhoto")} icon="camera-outline" loading={p.loading} onPress={p.camera}/><Button {...p} label={p.t("choosePhoto")} icon="images-outline" secondary disabled={p.loading} onPress={p.gallery}/></View><Pressable style={p.s.scanner} disabled={p.loading} onPress={p.camera}>{p.image?<Image source={{uri:p.image}} style={p.s.scannerImage}/>:<View style={p.s.scannerEmpty}><Ionicons name="scan-outline" size={52} color={p.theme.primary}/></View>}<View style={p.s.scanFrame}><View style={p.s.scanLine}/></View><Text style={p.s.scanHint}>{p.t("scannerHint")}</Text></Pressable><Text style={p.s.label}>{p.t("searchByName")}</Text><View style={p.s.searchRow}><View style={p.s.searchInput}><Ionicons name="search" size={18} color={p.theme.muted}/><TextInput style={p.s.input} value={p.name} onChangeText={p.setName} editable={!p.loading} placeholder={p.t("searchPlaceholder")} placeholderTextColor={p.theme.subtle} onFocus={p.focusSearch} returnKeyType="search" onSubmitEditing={p.search}/></View><Pressable accessibilityRole="button" accessibilityLabel={p.t("search")} accessibilityState={{busy:p.loading,disabled:p.loading}} style={({pressed})=>[p.s.searchButton,(pressed||p.loading)&&p.s.pressed]} disabled={p.loading} onPress={p.search}>{p.loading?<ActivityIndicator color="#fff"/>:<Ionicons name="arrow-forward" size={21} color="#fff"/>}</Pressable></View></View>}
function Results(p:C&{name:string;model:string;category:string;image:string;market:{label:string;currency:string};identified:boolean;offers:NormalizedOffer[];loading:boolean;notice:Notice;money:(n:number,c?:string)=>string;favorite:(o:NormalizedOffer)=>void;alert:(o:NormalizedOffer)=>Promise<Notice>;favoriteOfferIds:Set<string|undefined>;alertOfferIds:Set<string|undefined>;home:()=>void;photo:()=>void;open:(o:NormalizedOffer)=>void}){const [newOnly,setNewOnly]=useState(false);const [freeShippingOnly,setFreeShippingOnly]=useState(false);const visible=useMemo(()=>filterOffers(p.offers,{newOnly,freeShippingOnly}),[p.offers,newOnly,freeShippingOnly]);const best=visible[0];const reset=()=>{setNewOnly(false);setFreeShippingOnly(false)};return <View style={p.s.stack}><Text style={p.s.eyebrow}>{p.t("results")}</Text><View style={p.s.productHero}>{p.image?<Image source={{uri:p.image}} style={p.s.productImage}/>:<View style={p.s.productEmpty}><Ionicons name="cube-outline" size={26} color={p.theme.primary}/></View>}<View style={p.s.flex}><Text style={p.s.title}>{p.name||p.t("notIdentified")}</Text><Text style={p.s.muted}>{[p.model,p.category,`${p.market.label} · ${p.market.currency}`].filter(Boolean).join(" · ")}</Text>{best&&<><Text style={p.s.bestLabel}>{p.t("bestPrice")}</Text><Text style={p.s.best}>{p.money(best.totalPrice,best.currency)}</Text></>}</View></View><NoticeBox {...p} notice={p.notice}/><View style={p.s.chips}><Chip {...p} text={p.t("all")} active={!newOnly&&!freeShippingOnly} action={reset}/><Chip {...p} text={p.t("new")} active={newOnly} action={()=>setNewOnly(v=>!v)}/><Chip {...p} text={p.t("freeShipping")} active={freeShippingOnly} action={()=>setFreeShippingOnly(v=>!v)}/></View>{p.loading?<Empty {...p} loading title={p.t("loadingOffers")} text={p.t("wait")}/>:!visible.length?<Empty {...p} title={p.identified?p.t("noOffers"):p.t("notIdentified")} text={p.t("noOffersHelp")}/>:visible.map(o=><Offer key={o.id} {...p} offer={o} all={visible} saved={p.favoriteOfferIds.has(o.id)} alerted={p.alertOfferIds.has(o.id)} open={()=>p.open(o)} save={()=>p.favorite(o)} alarm={()=>void p.alert(o)}/>)}</View>}
function Offer(p:C&{offer:NormalizedOffer;all:NormalizedOffer[];money:(n:number,c?:string)=>string;open?:()=>void;save:()=>void;alarm:()=>void;saved?:boolean;alerted?:boolean}){const badge=getOfferBadge(p.offer,p.all);return <Pressable style={p.s.offer} onPress={p.open}><Image source={{uri:p.offer.imageUrl}} style={p.s.offerImage}/><View style={p.s.flex}><View style={p.s.chips}><Text style={p.offer.matchType==="exact"?p.s.exact:p.s.similar}>{p.offer.matchType==="exact"?p.t("exact"):p.t("similar")}</Text>{badge&&<Text style={p.s.badge}>{badge}</Text>}</View><Text style={p.s.offerTitle} numberOfLines={2}>{p.offer.title}</Text><Text style={p.s.muted}>{p.offer.storeName} · {p.offer.matchConfidence}%</Text><Text style={p.s.price}>{p.money(p.offer.totalPrice,p.offer.currency)}</Text><Text style={p.s.shipping}>{p.offer.shippingPrice===0?p.t("shippingIncluded"):`+ ${p.money(p.offer.shippingPrice,p.offer.currency)} ${p.t("shipping")}`}</Text><View style={p.s.actions}><Pressable style={({pressed})=>[p.s.buy,pressed&&p.s.pressed]} onPress={()=>void Linking.openURL(p.offer.affiliateUrl??p.offer.productUrl)}><Text style={p.s.buyText}>{p.t("buy")}</Text></Pressable><Icon {...p} name={p.saved?"bookmark":"bookmark-outline"} label={p.t("save")} action={p.save} active={p.saved}/><Icon {...p} name={p.alerted?"notifications":"notifications-outline"} label={p.t("createAlert")} action={p.alarm} active={p.alerted}/></View></View></Pressable>}
function Saved(p:C&{items:SavedItem[];open:(x:SavedItem)=>void}){const [tab,setTab]=useState<SavedKind>("favorite");const tabs:[SavedKind,string][]=[["favorite",p.t("favorites")],["alert",p.t("alerts")],["history",p.t("history")]];const items=p.items.filter(x=>x.kind===tab);const none=tab==="favorite"?p.t("noFavorites"):tab==="alert"?p.t("noAlerts"):p.t("noHistory");return <View style={p.s.stack}><Text style={p.s.eyebrow}>{p.t("saved")}</Text><Text style={p.s.title}>{p.t("savedTitle")}</Text><View style={p.s.segments}>{tabs.map(([k,l])=><Pressable key={k} style={[p.s.segment,tab===k&&p.s.segmentOn]} onPress={()=>setTab(k)}><Text style={[p.s.segmentText,tab===k&&p.s.segmentTextOn]}>{l}</Text></Pressable>)}</View>{!items.length?<Empty {...p} title={none} text=""/>:<View>{items.map(x=><Pressable key={x.id} style={p.s.savedRow} onPress={()=>p.open(x)}>{x.imageUri?<Image source={{uri:x.imageUri}} style={p.s.savedImage}/>:<View style={p.s.savedEmpty}><Ionicons name="cube-outline" size={20} color={p.theme.primary}/></View>}<View style={p.s.flex}><Text style={p.s.savedTitle} numberOfLines={2}>{x.title}</Text><Text style={p.s.muted} numberOfLines={2}>{x.subtitle}</Text></View><Ionicons name="chevron-forward" size={20} color={p.theme.subtle}/></Pressable>)}</View>}</View>}
function Plans(p:C){const sub=useSubscriptions();const [message,setMessage]=useState("");const buy=async()=>{setMessage("");if(!sub.premiumPackage){await sub.refresh();return}if(await sub.purchasePremium())setMessage(p.t("purchaseSuccess"))};const restore=async()=>{setMessage("");setMessage(await sub.restorePurchases()?p.t("restoreSuccess"):p.t("nothingToRestore"))};const price=sub.price||p.t("pricePending");return <View style={p.s.stack}><Text style={p.s.eyebrow}>{p.t("plans")}</Text><Text style={p.s.title}>{p.t("plansTitle")}</Text><Plan {...p} title="Starter" price={p.t("free")} tag={!sub.isPremium?p.t("activePlan"):p.t("included")} features={[p.t("starterComparisons"),p.t("starterImages"),p.t("basicHistory")]} action={!sub.isPremium?p.t("activePlan"):p.t("included")} disabled onPress={()=>{}}/><Plan {...p} title="Premium" price={price} tag={sub.isPremium?p.t("activePlan"):p.t("recommended")} features={[p.t("premiumComparisons"),p.t("premiumImages"),p.t("premiumAlerts"),p.t("advancedPrefs")]} featured loading={sub.loading||sub.purchasing} action={sub.isPremium?p.t("activePlan"):sub.premiumPackage?p.t("subscribe"):p.t("retryProducts")} disabled={sub.isPremium} onPress={()=>void buy()}/>{sub.error?<NoticeBox {...p} notice={{title:p.t("purchaseError"),message:sub.error,tone:"error"}}/>:message?<NoticeBox {...p} notice={{title:p.t("plans"),message,tone:"success"}}/>:!sub.configured?<NoticeBox {...p} notice={{title:p.t("plans"),message:p.t("purchaseUnavailable"),tone:"warning"}}/>:null}<Pressable style={p.s.restore} disabled={sub.purchasing||!sub.configured} onPress={()=>void restore()}><Text style={p.s.edit}>{p.t("restorePurchases")}</Text></Pressable></View>}
function Plan(p:C&{title:string;price:string;tag:string;features:string[];featured?:boolean;loading?:boolean;disabled?:boolean;action:string;onPress:()=>void}){return <View style={[p.s.plan,p.featured&&p.s.planFeatured]}><View style={p.s.planHead}><View style={p.s.flex}><Text style={p.s.planTitle}>{p.title}</Text><Text style={p.s.planPrice}>{p.price}</Text></View><View style={p.s.planTag}><Text style={p.s.planTagText} numberOfLines={1} adjustsFontSizeToFit minimumFontScale={.7}>{p.tag}</Text></View></View>{p.features.map(x=><View key={x} style={p.s.feature}><Ionicons name="checkmark-circle" size={19} color={p.theme.success}/><Text style={p.s.featureText}>{x}</Text></View>)}<Button {...p} label={p.action} icon={p.featured?"diamond-outline":"checkmark-circle-outline"} secondary={!p.featured||p.disabled} loading={p.loading} disabled={p.disabled} onPress={p.onPress}/></View>}
function Profile(p:C&{language:Language;setLanguage:(v:Language)=>void;appearance:Appearance;setAppearance:(v:Appearance)=>void;notifications:boolean;setNotifications:(v:boolean)=>void;market:Market;setMarket:(v:Market)=>void;premium:boolean}){const auth=useAuth();const marketOptions=(Object.entries(markets) as [Market,(typeof markets)[Market]][]).map(([code,value])=>[code,`${value.label} · ${value.currency}`]);return <View style={p.s.stack}><Text style={p.s.eyebrow}>{p.t("profile")}</Text><Text style={p.s.title}>{auth.user?p.t("account"):p.t("signIn")}</Text><View style={p.s.settings}>{auth.user?<><Text style={p.s.savedTitle}>{auth.user.displayName||p.t("account")}</Text><Text style={p.s.muted}>{auth.user.email}</Text><Button {...p} label={p.t("signOut")} icon="log-out-outline" secondary loading={auth.busy} onPress={()=>void auth.signOut()}/></>:<><Text style={p.s.muted}>{p.t("accountSync")}</Text><Button {...p} label={p.t("google")} icon="logo-google" secondary loading={auth.busy} onPress={()=>void auth.signInWithGoogle()}/>{auth.error?<NoticeBox {...p} notice={{title:p.t("signInError"),message:auth.error,tone:"error"}}/>:null}{auth.appleAvailable&&<Button {...p} label={p.t("apple")} icon="logo-apple" secondary loading={auth.busy} onPress={()=>void auth.signInWithApple()}/>}</>}</View><Text style={p.s.subhead}>{p.t("language")}</Text><Options s={p.s} value={p.language} options={languages.map(x=>[x.code,x.label])} change={v=>p.setLanguage(v as Language)}/><Text style={p.s.subhead}>{p.t("appearance")}</Text><Options s={p.s} value={p.appearance} options={[["light",p.t("light")],["dark",p.t("dark")],["system",p.t("system")]]} change={v=>p.setAppearance(v as Appearance)}/><View style={p.s.settingRow}><View style={p.s.flex}><Text style={p.s.savedTitle}>{p.t("notifications")}</Text><Text style={p.s.muted}>{p.t("notificationText")}</Text></View><Switch value={p.notifications} onValueChange={p.setNotifications}/></View><Text style={p.s.subhead}>{p.t("country")}</Text>{p.premium?<Options s={p.s} value={p.market} options={marketOptions} change={v=>p.setMarket(v as Market)}/>:<View style={p.s.settingRow}><View><Text style={p.s.savedTitle}>Portugal · EUR</Text><Text style={p.s.muted}>{p.t("premiumRequiredText")}</Text></View></View>}</View>}
function Confirm(p:C&{visible:boolean;bottom:number;name:string;setName:(v:string)=>void;brand:string;setBrand:(v:string)=>void;model:string;setModel:(v:string)=>void;category:string;setCategory:(v:string)=>void;image:string;close:()=>void;compare:()=>void}){const [edit,setEdit]=useState(false);const form=useRef<ScrollView>(null);const revealField=()=>setTimeout(()=>form.current?.scrollToEnd({animated:true}),180);return <Modal visible={p.visible} transparent animationType="slide" onRequestClose={p.close}><KeyboardAvoidingView style={p.s.fill} behavior={Platform.OS==="ios"?"padding":"height"}><View style={p.s.backdrop}><View style={p.s.sheet}><View style={p.s.handle}/><View style={p.s.sheetHead}><View><Text style={p.s.eyebrow}>{p.t("confirmation")}</Text><Text style={p.s.sheetTitle}>{p.t("confirmProduct")}</Text></View><Icon {...p} name="close" label={p.t("close")} action={p.close}/></View><ScrollView ref={form} style={p.s.sheetScroll} contentContainerStyle={p.s.sheetBody} keyboardShouldPersistTaps="handled" keyboardDismissMode="on-drag" automaticallyAdjustKeyboardInsets={Platform.OS==="ios"}>{p.image&&<Image source={{uri:p.image}} style={p.s.sheetImage}/>} {edit?<><Field {...p} label={p.t("product")} value={p.name} change={p.setName} focus={revealField}/><Field {...p} label={p.t("brandModel")} value={[p.brand,p.model].filter(Boolean).join(" ")} change={p.setModel} focus={revealField}/><Field {...p} label={p.t("category")} value={p.category} change={p.setCategory} focus={revealField}/></>:<View><Info s={p.s} label={p.t("product")} value={p.name}/><Info s={p.s} label={p.t("brandModel")} value={[p.brand,p.model].filter(Boolean).join(" ")||"—"}/><Info s={p.s} label={p.t("category")} value={p.category||"—"}/><Pressable onPress={()=>setEdit(true)}><Text style={p.s.edit}>{p.t("edit")}</Text></Pressable></View>}</ScrollView><View style={[p.s.sheetFoot,{paddingBottom:p.bottom}]}><Button {...p} label={p.t("comparePrices")} icon="checkmark-circle-outline" onPress={p.compare}/></View></View></View></KeyboardAvoidingView></Modal>}
function Product(p:C&{item:SavedItem|null;offers:NormalizedOffer[];money:(n:number,c?:string)=>string;bottom:number;close:()=>void;favorite:(o:NormalizedOffer)=>void;alert:(o:NormalizedOffer)=>Promise<Notice>;editAlert:(item:SavedItem,target:number)=>Promise<void>;removeAlert:(item:SavedItem)=>Promise<void>;favoriteOfferIds:Set<string|undefined>;alertOfferIds:Set<string|undefined>}){
  const [editing,setEditing]=useState(false);const [target,setTarget]=useState("");const [saving,setSaving]=useState(false);const [editError,setEditError]=useState("");const [actionNotice,setActionNotice]=useState<Notice|null>(null);const [history,setHistory]=useState<PriceObservation[]>([]);
  useEffect(()=>{setEditing(false);setEditError("");setActionNotice(null);setTarget(p.item?.alertPrice?.toFixed(2)??"");const offer=p.item?.offer;const initial:PriceObservation[]=offer&&offer.totalPrice>0?[{id:`current_${offer.id}`,price:offer.totalPrice,currency:offer.currency,storeName:offer.storeName,observedAt:new Date().toISOString()}]:[];setHistory(initial);if(p.item?.remoteId)void apiRequest<{items:PriceObservation[]}>(`/price-alerts/${p.item.remoteId}/history`,"GET").then(response=>setHistory(response.items.length?response.items:initial)).catch(()=>undefined)},[p.item?.id,p.item?.alertPrice,p.item?.remoteId]);
  if(!p.item)return null;
  const item=p.item;const list=item.offer?[item.offer,...p.offers.filter(x=>x.id!==item.offer?.id)]:p.offers;const purchase=analysePurchase(history);
  const saveTarget=async()=>{const value=Number(target.replace(",","."));if(!Number.isFinite(value)||value<=0){setEditError(p.t("apiUnavailable"));return}setSaving(true);setEditError("");try{await p.editAlert(item,value);setEditing(false)}catch{setEditError(p.t("apiUnavailable"))}finally{setSaving(false)}};
  const confirmRemove=()=>Alert.alert(p.t("removeAlert"),p.t("removeAlertConfirm"),[{text:p.t("close"),style:"cancel"},{text:p.t("removeAlert"),style:"destructive",onPress:()=>{setSaving(true);void p.removeAlert(item).catch(()=>setEditError(p.t("apiUnavailable"))).finally(()=>setSaving(false))}}]);
  const runAlert=async(offer:NormalizedOffer)=>{setSaving(true);setActionNotice(null);try{setActionNotice(await p.alert(offer))}finally{setSaving(false)}};
  return <Modal visible animationType="slide" onRequestClose={p.close}><SafeAreaView style={p.s.safe}><View style={p.s.detailHead}><Icon {...p} name="arrow-back" label={p.t("back")} action={p.close}/><Text style={p.s.savedTitle}>{p.t("productDetails")}</Text><View style={{width:40}}/></View><ScrollView contentContainerStyle={[p.s.detail,{paddingBottom:p.bottom+24}]}><View style={p.s.productSummary}>{item.imageUri?<Image source={{uri:item.imageUri}} style={p.s.summaryImage}/>:<View style={p.s.summaryImage}/>}<View style={p.s.flex}><Text style={p.s.summaryTitle}>{item.title}</Text>{item.offer&&<Text style={p.s.summaryPrice}>{p.money(item.offer.totalPrice,item.offer.currency)}</Text>}{purchase&&<Text style={[p.s.summaryRating,purchase.rating==="good"&&p.s.ratingGood,purchase.rating==="high"&&p.s.ratingHigh]}>{purchase.rating==="good"?p.t("goodPrice"):purchase.rating==="high"?p.t("highPrice"):purchase.rating==="normal"?p.t("normalPrice"):p.t("insufficientHistory")}</Text>}<Text style={p.s.muted}>{item.subtitle}</Text></View></View>{actionNotice&&<NoticeBox {...p} notice={actionNotice}/>} {item.alertPrice!=null&&<View style={p.s.alertBox}><Text style={p.s.label}>{p.t("targetPrice")}</Text>{editing?<><TextInput style={p.s.field} value={target} onChangeText={setTarget} keyboardType="decimal-pad" autoFocus selectTextOnFocus/><View style={p.s.row}><Button {...p} label={p.t("close")} icon="close" secondary onPress={()=>setEditing(false)}/><Button {...p} label={p.t("save")} icon="checkmark" loading={saving} onPress={()=>void saveTarget()}/></View>{editError?<Text style={p.s.errorText}>{editError}</Text>:null}</>:<><Text style={p.s.planPrice}>{p.money(item.alertPrice,item.offer?.currency)}</Text><Pressable onPress={()=>setEditing(true)} style={({pressed})=>pressed&&p.s.pressed}><Text style={p.s.edit}>{p.t("editAlert")}</Text></Pressable><Pressable disabled={saving} onPress={confirmRemove} style={({pressed})=>pressed&&p.s.pressed}><Text style={p.s.errorText}>{p.t("removeAlert")}</Text></Pressable></>}</View>}<PurchaseAnalysisCard {...p} history={history}/>{item.kind!=="alert"&&item.offer&&<Button {...p} label={p.alertOfferIds.has(item.offer.id)?p.t("removeAlert"):p.t("createAlert")} icon={p.alertOfferIds.has(item.offer.id)?"notifications":"notifications-outline"} loading={saving} onPress={()=>void runAlert(item.offer!)}/>}<Text style={p.s.subhead}>{p.t("availableOffers")}</Text>{list.length?list.map(o=><Offer key={o.id} {...p} offer={o} all={list} saved={p.favoriteOfferIds.has(o.id)} alerted={p.alertOfferIds.has(o.id)} save={()=>p.favorite(o)} alarm={()=>void runAlert(o)}/>):<Empty {...p} title={p.t("noOffers")} text={p.t("noOffersHelp")}/>}</ScrollView></SafeAreaView></Modal>
}
function PurchaseAnalysisCard(p:C&{history:PriceObservation[];money:(n:number,c?:string)=>string}){
  const analysis=analysePurchase(p.history);const {width}=useWindowDimensions();const chartWidth=Math.max(270,Math.min(520,width-64));
  if(!analysis)return <View style={p.s.analysisCard}><View style={p.s.analysisHead}><Text style={p.s.subhead}>{p.t("priceHistory")}</Text><Text style={p.s.rating}>{p.t("insufficientHistory")}</Text></View><View style={[p.s.lineChart,{width:chartWidth}]}>{[28,85,142].map(top=><View key={top} style={[p.s.gridRow,{top,left:42,width:chartWidth-56}]}/>)}</View><Text style={p.s.muted}>{p.t("noPriceHistory")}</Text></View>;
  const labels={good:p.t("goodPrice"),normal:p.t("normalPrice"),high:p.t("highPrice"),insufficient:p.t("insufficientHistory")};
  const recommendations={good:p.t("buyRecommendation"),normal:p.t("compareRecommendation"),high:p.t("waitRecommendation"),insufficient:p.t("historyRecommendation")};
  const points=p.history.slice(-8);const plotLeft=42;const plotRight=chartWidth-14;const plotTop=16;const plotBottom=154;const range=Math.max(analysis.maximum-analysis.minimum,1);
  const coordinates=points.map((point,index)=>({point,x:points.length===1?(plotLeft+plotRight)/2:plotLeft+(index*(plotRight-plotLeft))/(points.length-1),y:plotTop+((analysis.maximum-point.price)/range)*(plotBottom-plotTop)}));
  const currency=points.at(-1)?.currency;
  return <View style={p.s.analysisCard}>
    <View style={p.s.analysisHead}><Text style={p.s.subhead}>{p.t("priceHistory")}</Text><Text style={[p.s.rating,analysis.rating==="good"&&p.s.ratingGood,analysis.rating==="high"&&p.s.ratingHigh]}>{labels[analysis.rating]}</Text></View>
    <View style={[p.s.lineChart,{width:chartWidth}]}>
      {[analysis.maximum,(analysis.maximum+analysis.minimum)/2,analysis.minimum].map((value,index)=><View key={index} style={[p.s.gridRow,{top:plotTop+index*((plotBottom-plotTop)/2),width:plotRight-plotLeft,left:plotLeft}]}><Text style={p.s.axisPrice}>{p.money(value,currency)}</Text></View>)}
      {coordinates.slice(0,-1).map((point,index)=>{const next=coordinates[index+1];const dx=next.x-point.x;const dy=next.y-point.y;const length=Math.sqrt(dx*dx+dy*dy);return <View key={`line-${index}`} style={[p.s.chartLine,{left:(point.x+next.x)/2-length/2,top:(point.y+next.y)/2-1,width:length,transform:[{rotate:`${Math.atan2(dy,dx)}rad`}]}]}/>})}
      {coordinates.map(({point,x,y},index)=><View key={point.id}><View style={[p.s.chartDot,{left:x-4,top:y-4}]}/><Text style={[p.s.axisDate,{left:Math.max(0,x-24),top:plotBottom+10}]}>{index===0||index===coordinates.length-1||coordinates.length<=5?new Date(point.observedAt).toLocaleDateString(undefined,{day:"2-digit",month:"short"}):""}</Text></View>)}
    </View>
    <View style={p.s.statRow}><Stat {...p} label={p.t("historicalLow")} value={p.money(analysis.minimum,currency)}/><Stat {...p} label={p.t("historicalAverage")} value={p.money(analysis.average,currency)}/><Stat {...p} label={p.t("historicalHigh")} value={p.money(analysis.maximum,currency)}/></View>
    <View style={p.s.aiHead}><Ionicons name="sparkles-outline" size={18} color={p.theme.primaryStrong}/><Text style={p.s.savedTitle}>{p.t("priceLensAi")}</Text></View>
    <Text style={p.s.recommendation}>{recommendations[analysis.rating]}</Text>
  </View>
}
function Stat(p:C&{label:string;value:string}){return <View style={p.s.stat}><Text style={p.s.label}>{p.label}</Text><Text style={p.s.savedTitle}>{p.value}</Text></View>}
function Tabs(p:C&{active:Screen;change:(v:Screen)=>void;bottom:number}){const tabs:[Screen,string,keyof typeof Ionicons.glyphMap][]=[["home",p.t("home"),"scan-outline"],["results",p.t("results"),"pricetag-outline"],["saved",p.t("saved"),"bookmark-outline"],["plans",p.t("plans"),"diamond-outline"],["profile",p.t("profile"),"person-outline"]];return <View style={[p.s.tabs,{paddingBottom:p.bottom}]}>{tabs.map(([k,l,i])=><Pressable key={k} style={[p.s.tab,p.active===k&&p.s.tabOn]} onPress={()=>p.change(k)}><Ionicons name={i} size={20} color={p.active===k?p.theme.primaryStrong:p.theme.muted}/><Text style={[p.s.tabText,p.active===k&&p.s.tabTextOn]} numberOfLines={1} adjustsFontSizeToFit>{l}</Text></Pressable>)}</View>}
function Button(p:C&{label:string;icon:keyof typeof Ionicons.glyphMap;secondary?:boolean;loading?:boolean;disabled?:boolean;onPress:()=>void}){const inactive=p.loading||p.disabled;return <Pressable accessibilityRole="button" accessibilityState={{disabled:inactive}} style={[p.s.button,p.secondary?p.s.buttonSecondary:p.s.buttonPrimary,inactive&&{opacity:.6}]} disabled={inactive} onPress={p.onPress}>{p.loading?<ActivityIndicator color={p.secondary?p.theme.primary:"#fff"}/>:<Ionicons name={p.icon} size={19} color={p.secondary?p.theme.ink:"#fff"}/>}<Text style={p.secondary?p.s.buttonTextSecondary:p.s.buttonText} numberOfLines={2}>{p.label}</Text></Pressable>}
function Icon(p:C&{name:keyof typeof Ionicons.glyphMap;label:string;action:()=>void;active?:boolean}){return <Pressable style={({pressed})=>[p.s.icon,p.active&&p.s.iconActive,pressed&&p.s.pressed]} onPress={p.action} accessibilityRole="button" accessibilityLabel={p.label} accessibilityState={{selected:p.active}}><Ionicons name={p.name} size={20} color={p.active?p.theme.primaryStrong:p.theme.ink}/></Pressable>}
function NoticeBox(p:C&{notice:Notice}){return <View style={[p.s.notice,p.notice.tone==="warning"&&p.s.noticeWarn,p.notice.tone==="error"&&p.s.noticeError]}><Ionicons name={p.notice.tone==="success"?"checkmark-circle-outline":"information-circle-outline"} size={20} color={p.notice.tone==="success"?p.theme.success:p.notice.tone==="warning"?p.theme.warning:p.theme.danger}/><View style={p.s.flex}><Text style={p.s.savedTitle}>{p.notice.title}</Text><Text style={p.s.muted}>{p.notice.message}</Text></View></View>}
function Empty(p:C&{title:string;text:string;loading?:boolean;actions?:React.ReactNode}){return <View style={p.s.empty}>{p.loading?<ActivityIndicator color={p.theme.primary}/>:<Ionicons name="search-outline" size={30} color={p.theme.primary}/>}<Text style={p.s.emptyTitle}>{p.title}</Text>{p.text&&<Text style={p.s.emptyText}>{p.text}</Text>}{p.actions}</View>}
function Chip(p:C&{text:string;active?:boolean;action:()=>void}){return <Pressable accessibilityRole="button" accessibilityState={{selected:p.active}} onPress={p.action} style={({pressed})=>pressed&&p.s.pressed}><Text style={[p.s.chip,p.active&&p.s.chipOn]}>{p.text}</Text></Pressable>}
function Field(p:C&{label:string;value:string;change:(v:string)=>void;focus?:()=>void}){return <View><Text style={p.s.label}>{p.label}</Text><TextInput style={p.s.field} value={p.value} onChangeText={p.change} onFocus={p.focus} placeholderTextColor={p.theme.subtle}/></View>}
function Info({s,label,value}:{s:ReturnType<typeof styles>;label:string;value:string}){return <View style={s.info}><Text style={s.label}>{label}</Text><Text style={s.infoValue}>{value}</Text></View>}
function Options({s,value,options,change}:{s:ReturnType<typeof styles>;value:string;options:string[][];change:(v:string)=>void}){return <View style={s.options}>{options.map(([v,l])=><Pressable key={v} style={[s.option,value===v&&s.optionOn]} onPress={()=>change(v)}><Text style={[s.optionText,value===v&&s.optionTextOn]}>{l}</Text></Pressable>)}</View>}

